import java.util.*;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long n = sc.nextLong();
        ArrayList<Long>[] v = new ArrayList[11];
        for (int i = 0; i < v.length; i++) {
            v[i] = new ArrayList<>();
        }
        long[] s = new long[11];
        final long M1 = 998244353;
        final long M2 = 1000000007;
        long count = 0, temp_count = 0, result = 0;

        Function<Long, Long> mod1 = (x) -> ((x % M1) + M1) % M1;

        // build1 recursive method
        class Build1 {
            void execute(int level, long val) {
                if (val > n) return;
                if (level > 6) return;
                ++count;
                long valMod = mod1.apply(count - val);
                v[level].add(valMod);
                s[level] += valMod;
                for (int d = 0; d <= 9; d++) {
                    execute(level + 1, val * 10 + d);
                }
            }
        }

        // build2 recursive method
        class Build2 {
            void execute(int level, long val) {
                if (val > n) return;
                if (level >= 1) {
                    if (val * 10 * n > n && val * n + n - 1 <= n) {
                        for (int i = 0; i <= 6; i++) {
                            long v1 = mod1.apply(count - val);
                            List<Long> vec = v[i];
                            int pos = lowerBound(vec, M1 - v1);
                            long sum = v1 * vec.size() + s[i] - M1 * (vec.size() - pos);
                            sum = ((sum % M2) + M2) % M2; // ensure non-negative
                            result = (result + sum) % M2;
                        }
                        count += temp_count;
                        return;
                    }
                    ++count;
                    long valMod = mod1.apply(count - val);
                    result = (result + valMod) % M2;
                }
                int startD = (level == 0) ? 1 : 0;
                for (int d = startD; d <= 9; d++) {
                    execute(level + 1, val * 10 + d);
                }
            }
        }

        // Helper method for binary search (lower_bound)
        int lowerBound(List<Long> list, long key) {
            int low = 0, high = list.size();
            while (low < high) {
                int mid = (low + high) / 2;
                if (list.get(mid) >= key) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }
            return low;
        }

        Build1 build1 = new Build1();
        build1.execute(0, 0);
        temp_count = count;
        count = 0;

        for (int i = 0; i <= 6; i++) {
            Collections.sort(v[i]);
        }

        Build2 build2 = new Build2();
        build2.execute(0, 0);

        System.out.println(result);
    }
}
